function bar() {}
```

### Recommended
```js
// explicitly set on window
window.foo = 1;
window.bar = function() {};

// intended to be scope to this file
(function() {
  let foo = 1;
  function bar() {}
})();

// correct code for ES Modules
// foo and bar are local to module
